const body = $input.first().json.body;
const required = ['destination', 'arrival_date', 'departure_date', 'travel_style'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const arrival = new Date(body.arrival_date);
const departure = new Date(body.departure_date);
if (isNaN(arrival) || isNaN(departure)) return [{ json: { valid: false, error: 'Invalid date format — use YYYY-MM-DD' } }];
const nights = Math.round((departure - arrival) / 86400000);
if (nights < 1 || nights > 21) return [{ json: { valid: false, error: 'Trip must be 1-21 nights' } }];
const validStyles = ['budget', 'mid_range', 'luxury', 'backpacker', 'family', 'romantic', 'adventure', 'cultural', 'foodie', 'slow_travel'];
const style = validStyles.includes(body.travel_style) ? body.travel_style : 'mid_range';
return [{ json: {
  valid: true,
  destination: body.destination.trim(),
  arrivalDate: body.arrival_date,
  departureDate: body.departure_date,
  nights,
  travelStyle: style,
  travelers: parseInt(body.travelers) || 2,
  budget: body.budget || '',
  currency: body.currency || 'USD',
  interests: Array.isArray(body.interests) ? body.interests : (body.interests || '').split(',').map(s => s.trim()).filter(Boolean),
  dietaryNeeds: body.dietary_needs || '',
  mobilityNeeds: body.mobility_needs || '',
  mustSee: (body.must_see || '').slice(0, 400),
  avoidList: (body.avoid || '').slice(0, 300),
  accommodationBooked: body.accommodation_booked === true || body.accommodation_booked === 'true',
  flightsBooked: body.flights_booked === true || body.flights_booked === 'true',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const search = $('Research Destination').first().json;
const input = $('Validate Input').first().json;
const context = (search.results||[]).map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,350)}`).join('\n\n');
return [{ json: { input, destinationContext: context || 'No additional context found.' } }];

values.content:
Build a travel itinerary.

Destination: {{ $json.input.destination }}
Dates: {{ $json.input.arrivalDate }} to {{ $json.input.departureDate }} ({{ $json.input.nights }} nights)
Travelers: {{ $json.input.travelers }} people
Travel style: {{ $json.input.travelStyle.replace('_',' ') }}
Budget: {{ $json.input.budget || 'not specified' }} {{ $json.input.currency }}
Interests: {{ $json.input.interests.join(', ') || 'not specified' }}
Dietary needs: {{ $json.input.dietaryNeeds || 'none' }}
Mobility considerations: {{ $json.input.mobilityNeeds || 'none' }}
Must-see/do: {{ $json.input.mustSee || 'none specified' }}
Avoid: {{ $json.input.avoidList || 'nothing specified' }}
Accommodation booked: {{ $json.input.accommodationBooked }}
Flights booked: {{ $json.input.flightsBooked }}

Destination research context:
{{ $json.destinationContext }}

Return this JSON:
{
  "destination": "{{ $json.input.destination }}",
  "trip_overview": "2-3 sentences on what makes this destination special for these travelers at this time of year — be specific",
  "travel_tips": ["3-5 practical tips specific to this destination and travel style — things most guides don't emphasize enough"],
  "days": [
    {
      "day": 1,
      "date": "{{ $json.input.arrivalDate }}",
      "theme": "short evocative theme for the day e.g. Arrival & Old City",
      "morning": { "activity": "what to do", "location": "specific place name", "duration": "approx time", "tip": "practical insider tip" },
      "afternoon": { "activity": "what to do", "location": "specific place name", "duration": "approx time", "tip": "practical tip" },
      "evening": { "activity": "what to do", "location": "specific place/neighbourhood", "duration": "approx time", "tip": "practical tip" },
      "meal_suggestions": { "breakfast": "specific cafe or style", "lunch": "specific restaurant or area", "dinner": "specific restaurant or neighbourhood" },
      "logistics_note": "transport, booking requirements, best time to arrive — any logistical detail that makes the day flow"
    }
  ],
  "accommodation_suggestion": "{{ $json.input.accommodationBooked ? 'Accommodation already booked — no suggestion needed' : 'specific neighbourhood and 1-2 property types or names suited to this travel style' }}",
  "getting_around": "practical transport overview for this destination — what works, what to avoid, costs",
  "budget_guide": "realistic daily spend estimate per person for this travel style — broken into accommodation/food/activities/transport",
  "what_to_skip": ["1-3 overrated things at this destination that don't match this trip's style or value"],
  "packing_note": "one specific packing consideration for this destination and dates that travelers often miss"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let itinerary;
try { itinerary = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
itinerary._meta = { nights: input.nights, travelers: input.travelers, travelStyle: input.travelStyle, arrivalDate: input.arrivalDate, departureDate: input.departureDate, replyEmail: input.replyEmail, currency: input.currency };
return [{ json: itinerary }];

const it = $input.first().json;
const m = it._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const dayCards = (it.days||[]).map((d,i) => {
  const slots = ['morning','afternoon','evening'].map(slot => {
    const s = d[slot]; if (!s) return '';
    return `<div style="margin-bottom:12px">
      <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:3px">${slot}</div>
      <div style="font-size:14px;font-weight:600">${esc(s.activity)}</div>
      <div style="font-size:13px;color:#6b7280">${esc(s.location)} · ${esc(s.duration)}</div>
      <div style="font-size:13px;color:#2563eb;margin-top:3px">💡 ${esc(s.tip)}</div>
    </div>`;
  }).join('');
  const meals = d.meal_suggestions ? `<div style="background:#f9fafb;border-radius:6px;padding:10px 14px;margin-top:12px;font-size:13px">
    <div style="font-weight:700;margin-bottom:5px;color:#374151">🍽 Meals</div>
    ${d.meal_suggestions.breakfast?`<div><strong>Breakfast:</strong> ${esc(d.meal_suggestions.breakfast)}</div>`:''}
    ${d.meal_suggestions.lunch?`<div><strong>Lunch:</strong> ${esc(d.meal_suggestions.lunch)}</div>`:''}
    ${d.meal_suggestions.dinner?`<div><strong>Dinner:</strong> ${esc(d.meal_suggestions.dinner)}</div>`:''}
  </div>` : '';
  const logistics = d.logistics_note ? `<div style="background:#eff6ff;border-radius:6px;padding:8px 14px;margin-top:10px;font-size:13px;color:#1d4ed8">📍 ${esc(d.logistics_note)}</div>` : '';
  return `<div style="border:1px solid #e5e7eb;border-radius:8px;margin-bottom:16px;overflow:hidden">
    <div style="background:#1e293b;color:#fff;padding:10px 18px;display:flex;justify-content:space-between;align-items:center">
      <div><span style="font-size:12px;font-weight:700;color:#94a3b8">Day ${d.day}</span> <span style="font-size:14px;font-weight:700;margin-left:8px">${esc(d.theme)}</span></div>
      <span style="font-size:12px;color:#64748b">${esc(d.date||'')}</span>
    </div>
    <div style="padding:16px 18px">${slots}${meals}${logistics}</div>
  </div>`;
}).join('');

const tipsList = (it.travel_tips||[]).map(t=>`<li style="font-size:14px;margin-bottom:8px;line-height:1.55;color:#374151">${esc(t)}</li>`).join('');
const skipList = (it.what_to_skip||[]).map(s=>`<div style="font-size:13px;color:#6b7280;padding:5px 0;border-bottom:1px solid #f3f4f6">✗ ${esc(s)}</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f0ea;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#1a3a2a;color:#fff;padding:22px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6db38a;margin-bottom:5px">${m.nights}-night itinerary · ${esc(m.travelStyle.replace(/_/g,' '))} · ${m.travelers} traveler${m.travelers>1?'s':''}</div>
    <div style="font-size:22px;font-weight:700">${esc(it.destination)}</div>
    <div style="font-size:13px;color:#6db38a;margin-top:4px">${esc(m.arrivalDate)} → ${esc(m.departureDate)}</div>
  </div>
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:none">
    <p style="font-size:15px;line-height:1.75;color:#374151;margin:0">${esc(it.trip_overview)}</p>
  </div>
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0ede8">
    ${dayCards}
  </div>
  ${tipsList ? `<div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0ede8">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Travel tips</div>
    <ul style="padding-left:18px;margin:0">${tipsList}</ul>
  </div>` : ''}
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0ede8">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
      <div>
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Getting around</div>
        <div style="font-size:14px;color:#374151;line-height:1.6">${esc(it.getting_around)}</div>
      </div>
      <div>
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Budget guide</div>
        <div style="font-size:14px;color:#374151;line-height:1.6">${esc(it.budget_guide)}</div>
      </div>
    </div>
  </div>
  ${it.accommodation_suggestion && !it.accommodation_suggestion.includes('already booked') ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f0ede8">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Where to stay</div>
    <div style="font-size:14px;color:#374151;line-height:1.6">${esc(it.accommodation_suggestion)}</div>
  </div>` : ''}
  ${skipList ? `<div style="background:#fef9f0;padding:14px 28px;border:1px solid #fde8c0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:7px">Worth skipping</div>
    ${skipList}
  </div>` : ''}
  ${it.packing_note ? `<div style="background:#f0fdf4;padding:12px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:5px">Pack this</div>
    <div style="font-size:14px;color:#166534;line-height:1.6">${esc(it.packing_note)}</div>
  </div>` : ''}
  <div style="background:#1a3a2a;color:#4a7a5a;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Travel Itinerary Builder · ${esc(it.destination)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, destination: it.destination, nights: m.nights, itinerary: it } }];
